1082		InstallFailReason string
1083		InstallFailAt     time.Time
1084		// RollbackResult 表示是否已接受回滚结果。
1085		RollbackResult bool
1086		// RollbackSuccess 表示已接受的回滚结果是否成功。
1087		RollbackSuccess bool
1088		// RollbackReason/RollbackAt 是回滚结果（成功或失败）的原因与时间。
1089		RollbackReason string
1090		RollbackAt     time.Time
1091	}
