1	package shadow
2	
3	import (
4		"encoding/json"
5		"errors"
6		"testing"
7		"time"
8	)
9	
10	// TestTwoDeviceRollbackFromDistinctOldVersions 回归同一活动、同一批次内两台设备
11	// 从各自不同的旧版本升级、先后安装失败后各自回滚的完整行为。
12	//
13	// 时间线（相对 upBase：窗口 [12:00,13:00)，截止 14:00）：
14	//
15	//	-2m/-90s 两台设备升级前各下发一份已修改的期望配置（修订号均为 1）
16	//	 12:02   dev-a 首次领取下载，锁定回滚目标 firmware-1.0-a
17	//	 12:03   dev-a 下载成功
18	//	 12:04   dev-a 领取安装
19	//	 12:05   dev-b 首次领取下载，锁定回滚目标 firmware-1.0-b
20	//	 12:06   dev-b 下载成功
21	//	 12:07   dev-b 领取安装
22	//	 12:08   dev-a 安装失败（原因 alpha）；dev-b 已领取的安装不受影响
23	//	 12:09   dev-b 安装失败（原因 beta）；两份回滚待办并存
24	//	 12:10/11 两台设备先后领取各自的回滚（操作标识互不相同）
25	//	 12:20   以 dev-a 身份提交 dev-b 已领取的回滚标识 -> ErrOperationNotFound
26	//	 12:21   dev-a 用自己的回滚标识、却填 dev-b 的恢复版本 -> ErrInvalidReport
27	//	 12:25   后失败的 dev-b 先提交合规回滚成功（恢复 v1-b）；活动继续执行
28	//	 12:30   dev-a 提交合规回滚成功（恢复 v1-a）；活动才以失败结束
29	//
30	// v1-a/v1-b 都只是目标版本允许的升级来源，不另行登记为升级目标。
31	func TestTwoDeviceRollbackFromDistinctOldVersions(t *testing.T) {
32		s, _ := openTemp(t)
33		const (
34			cid    = "cmp-2dev"
35			d1     = "dev-a"
36			d2     = "dev-b"
37			oldV1  = "firmware-1.0-a"
38			oldV2  = "firmware-1.0-b"
39			target = "firmware-2.0"
40		)
41		// 目标版本同时允许两个不同的旧版本；恢复用的旧版本不另行登记。
42		if err := s.RegisterUpgrade(target, []string{oldV1, oldV2}); err != nil {
43			t.Fatalf("RegisterUpgrade: %v", err)
44		}
45		mustRegister(t, s, d1, oldV1)
46		mustRegister(t, s, d2, oldV2)
47	
48		// 升级前两台设备各有一份已修改的期望配置，留存副本用于最终核对。
49		desired1 := json.RawMessage(`{"channel":1,"mode":"a"}`)
50		desired2 := json.RawMessage(`{"channel":2,"mode":"b"}`)
51		if rev, err := s.UpdateDesired(d1, "ops-a", upBase.Add(-2*time.Minute), 0, desired1); err != nil || rev != 1 {
52			t.Fatalf("d1 update desired: rev=%d err=%v", rev, err)
53		}
54		if rev, err := s.UpdateDesired(d2, "ops-b", upBase.Add(-90*time.Second), 0, desired2); err != nil || rev != 1 {
55			t.Fatalf("d2 update desired: rev=%d err=%v", rev, err)
56		}
57	
58		spec := upSpec()
59		spec.ID = cid
60		spec.TargetVersion = target
61		spec.Devices = []string{d1, d2}
62		spec.BatchSize = 2 // 两台设备同属批次 0
63		spec.RollbackOnFailure = true
64		createCampaign(t, s, spec)
65		// 用各自旧版本的正整数序号上报让两台设备上线（不能复用硬编码 v1 的 bringOnline）。
66		if err := s.Report(d1, 1, upBase.Add(-time.Minute), oldV1, json.RawMessage(`{}`)); err != nil {
67			t.Fatalf("d1 online report: %v", err)
68		}
69		if err := s.Report(d2, 1, upBase.Add(-time.Minute), oldV2, json.RawMessage(`{}`)); err != nil {
70			t.Fatalf("d2 online report: %v", err)
71		}
72	
73		dv := func(id string) DeviceStatusView {
74			t.Helper()
75			return findDevice(mustGetCampaign(s, cid), id)
76		}
77		claim := func(id string, at time.Time, wantStage string) *Operation {
78			t.Helper()
79			op, err := s.Claim(cid, id, at)
80			if err != nil {
81				t.Fatalf("claim %s %s at %v: %v", id, wantStage, at, err)
82			}
83			if op == nil || op.Kind != wantStage {
84				t.Fatalf("claim %s %s: got %+v", id, wantStage, op)
85			}
86			return op
87		}
88		submit := func(r OperationResult) {
89			t.Helper()
90			if err := s.SubmitResult(r); err != nil {
91				t.Fatalf("submit result: %v", err)
92			}
93		}
94	
95		// 两台设备在同一批次。
96		if a, b := dv(d1), dv(d2); a.Batch != 0 || b.Batch != 0 {
97			t.Fatalf("devices must share batch 0: %+v %+v", a, b)
98		}
99	
100		// dev-a 先后完成下载、领取安装；首次领取下载锁定其当时版本 v1-a。
101		dl1 := claim(d1, upBase.Add(2*time.Minute), StageDownload)
102		if tgt := dv(d1).RollbackTarget; tgt != oldV1 {
103			t.Fatalf("d1 rollback target locked at first download claim: %q", tgt)
104		}
105		submit(OperationResult{
106			CampaignID: cid, DeviceID: d1, OperationID: dl1.ID,
107			At: upBase.Add(3 * time.Minute), Success: true,
108		})
109		in1 := claim(d1, upBase.Add(4*time.Minute), StageInstall)
110	
111		// dev-b 同样在窗口内领取下载（锁定 v1-b）、完成下载、领取安装。
112		dl2 := claim(d2, upBase.Add(5*time.Minute), StageDownload)
113		if tgt := dv(d2).RollbackTarget; tgt != oldV2 {
114			t.Fatalf("d2 rollback target locked at first download claim: %q", tgt)
115		}
116		submit(OperationResult{
117			CampaignID: cid, DeviceID: d2, OperationID: dl2.ID,
118			At: upBase.Add(6 * time.Minute), Success: true,
119		})
120		in2 := claim(d2, upBase.Add(7*time.Minute), StageInstall)
121	
122		// dev-a 先安装失败；原因/时间保留，转入等待回滚。
123		fail1At := upBase.Add(8 * time.Minute)
124		submit(OperationResult{
125			CampaignID: cid, DeviceID: d1, OperationID: in1.ID,
126			At: fail1At, Success: false, Reason: "install fail alpha",
127		})
128		if a := dv(d1); a.Status != DeviceAwaitingRollback || a.Phase != StageRollback ||
129			a.InstallFailReason != "install fail alpha" || !a.InstallFailAt.Equal(fail1At) {
130			t.Fatalf("d1 awaiting rollback with own failure: %+v", a)
131		}
132		// dev-a 失败时，dev-b 仍能查到并完成自己已领取的安装（同一标识）。
133		out, err := s.Claim(cid, d2, upBase.Add(8*time.Minute+30*time.Second))
134		if err != nil || out == nil || out.ID != in2.ID || out.Kind != StageInstall {
135			t.Fatalf("d2 claimed install must survive d1 failure: %v %+v", err, out)
136		}
137		if b := dv(d2); b.Status != DeviceInstalling || b.InstallFailReason != "" {
138			t.Fatalf("d2 keeps installing untouched by d1 failure: %+v", b)
139		}
140	
141		// dev-b 随后提交自己的、原因不同的安装失败；两台设备的失败原因与时间
142		// 各自保留，不能被另一台的失败记录替换。
143		fail2At := upBase.Add(9 * time.Minute)
144		submit(OperationResult{
145			CampaignID: cid, DeviceID: d2, OperationID: in2.ID,
146			At: fail2At, Success: false, Reason: "install fail beta",
147		})
148		v := mustGetCampaign(s, cid)
149		if v.Ended || v.Status != CampaignRunning || !v.EndedAt.IsZero() {
150			t.Fatalf("campaign must wait for both rollbacks: %+v", v)
151		}
152		a, b := dv(d1), dv(d2)
153		if a.Status != DeviceAwaitingRollback || a.RollbackTarget != oldV1 ||
154			a.InstallFailReason != "install fail alpha" || !a.InstallFailAt.Equal(fail1At) {
155			t.Fatalf("d1 failure record overwritten by d2: %+v", a)
156		}
157		if b.Status != DeviceAwaitingRollback || b.RollbackTarget != oldV2 ||
158			b.InstallFailReason != "install fail beta" || !b.InstallFailAt.Equal(fail2At) {
159			t.Fatalf("d2 failure record: %+v", b)
160		}
161		// 两份回滚待办并存：目标是各自首次领取下载时的版本，操作标识互不相同，
162		// 且与各自的下载、安装标识区分。
163		rb1Want := encodeOperationIDV2(0, cid, d1, StageRollback)
164		rb2Want := encodeOperationIDV2(0, cid, d2, StageRollback)
165		if a.RollbackID != rb1Want || b.RollbackID != rb2Want ||
166			rb1Want == rb2Want ||
167			rb1Want == dl1.ID || rb1Want == in1.ID ||
168			rb2Want == dl2.ID || rb2Want == in2.ID {
169			t.Fatalf("rollback ids must be distinct per device/stage: %q %q (dl1=%s in1=%s dl2=%s in2=%s)",
170				a.RollbackID, b.RollbackID, dl1.ID, in1.ID, dl2.ID, in2.ID)
171		}
172		for _, tc := range []struct {
173			id, target string
174		}{{d1, oldV1}, {d2, oldV2}} {
175			w, err := s.GetDeviceWork(tc.id)
176			if err != nil {
177				t.Fatalf("work %s: %v", tc.id, err)
178			}
179			if w.Pending == nil || w.Pending.Kind != StageRollback || w.PendingClaimed ||
180				w.Pending.TargetVersion != tc.target {
181				t.Fatalf("unclaimed rollback todo for %s: %+v", tc.id, w)
182			}
183		}
184		// 安装失败阶段两台设备的影子版本仍是各自旧版本，序号沿用现有规则。
185		if sh, _ := s.Get(d1); sh.Version != oldV1 || sh.LastSeq != 1 {
186			t.Fatalf("d1 shadow after install failure: %+v", sh)
187		}
188		if sh, _ := s.Get(d2); sh.Version != oldV2 || sh.LastSeq != 1 {
189			t.Fatalf("d2 shadow after install failure: %+v", sh)
190		}
191	
192		// 两台设备先后在窗口内领取各自的回滚。
193		rb1 := claim(d1, upBase.Add(10*time.Minute), StageRollback)
194		if rb1.ID != rb1Want || rb1.TargetVersion != oldV1 {
195			t.Fatalf("d1 rollback op: %+v", rb1)
196		}
197		rb2 := claim(d2, upBase.Add(11*time.Minute), StageRollback)
198		if rb2.ID != rb2Want || rb2.TargetVersion != oldV2 {
199			t.Fatalf("d2 rollback op: %+v", rb2)
200		}
201	
202		// 两种与设备归属直接相关的拒绝行为，均不得改变任一设备的影子、
203		// 回滚进度或活动历史。
204		nHistory := len(mustGetCampaign(s, cid).Results) // 两条下载成功 + 两条安装失败
205		// 1) 以 dev-a 身份提交 dev-b 已领取的回滚操作标识：ErrOperationNotFound。
206		err = s.SubmitResult(OperationResult{
207			CampaignID: cid, DeviceID: d1, OperationID: rb2.ID,
208			At: upBase.Add(20 * time.Minute), Success: true,
209			Seq: 2, Version: oldV1, Config: json.RawMessage(`{}`),
210		})
211		if !errors.Is(err, ErrOperationNotFound) {
212			t.Fatalf("submit other device's rollback op: want ErrOperationNotFound, got %v", err)
213		}
214		// 2) dev-a 使用自己的回滚标识，却在成功结果里填入 dev-b 锁定的恢复版本：
215		//    序号与配置本身合规，唯一问题是恢复版本不属于本设备 -> ErrInvalidReport。
216		err = s.SubmitResult(OperationResult{
217			CampaignID: cid, DeviceID: d1, OperationID: rb1.ID,
218			At: upBase.Add(21 * time.Minute), Success: true,
219			Seq: 2, Version: oldV2, Config: json.RawMessage(`{"channel":1,"mode":"a"}`),
220		})
221		if !errors.Is(err, ErrInvalidReport) {
222			t.Fatalf("rollback to other device's locked version: want ErrInvalidReport, got %v", err)
223		}
224		// 两次拒绝后：两台设备仍是正在回滚、无回滚结果，安装失败记录原样保留，
225		// 影子不变，历史不增，活动继续执行。
226		cv := mustGetCampaign(s, cid)
227		if cv.Ended || cv.Status != CampaignRunning || len(cv.Results) != nHistory {
228			t.Fatalf("rejections changed campaign: %+v history=%d", cv, len(cv.Results))
229		}
230		for _, tc := range []struct {
231			id, old, reason string
232			failAt          time.Time
233		}{
234			{d1, oldV1, "install fail alpha", fail1At},
235			{d2, oldV2, "install fail beta", fail2At},
236		} {
237			d := findDevice(cv, tc.id)
238			if d.Status != DeviceRollingBack || d.RollbackResult ||
239				d.InstallFailReason != tc.reason || !d.InstallFailAt.Equal(tc.failAt) {
240				t.Fatalf("%s rollback progress changed by rejected submissions: %+v", tc.id, d)
241			}
242			if sh, _ := s.Get(tc.id); sh.Version != tc.old || sh.LastSeq != 1 {
243				t.Fatalf("%s shadow changed by rejected submissions: %+v", tc.id, sh)
244			}
245		}
246	
247		// 后发生安装失败的 dev-b 先提交回滚成功：附带自己的恢复版本和完整配置。
248		rbCfg2 := json.RawMessage(`{"channel":2,"mode":"b","restored":true}`)
249		rb2At := upBase.Add(25 * time.Minute)
250		submit(OperationResult{
251			CampaignID: cid, DeviceID: d2, OperationID: rb2.ID,
252			At: rb2At, Success: true,
253			Seq: 2, Version: oldV2, Config: rbCfg2,
254		})
255		// dev-b 当前版本、上报配置与回滚状态随结果更新；期望配置/修订号不动。
256		sh2, _ := s.Get(d2)
257		if sh2.Version != oldV2 || !sh2.Online || sh2.LastSeq != 2 || !rawEqual(sh2.Reported, rbCfg2) {
258			t.Fatalf("d2 shadow after rollback success: %+v", sh2)
259		}
260		if sh2.Revision != 1 || !rawEqual(sh2.Desired, desired2) {
261			t.Fatalf("d2 desired changed by rollback: rev=%d desired=%s", sh2.Revision, sh2.Desired)
262		}
263		b = dv(d2)
264		if b.Status != DeviceRollbackSucceeded || b.Phase != StageRollback ||
265			!b.RollbackResult || !b.RollbackSuccess || !b.RollbackAt.Equal(rb2At) ||
266			b.RollbackReason != "" ||
267			b.InstallFailReason != "install fail beta" || !b.InstallFailAt.Equal(fail2At) {
268			t.Fatalf("d2 rollback-succeeded record: %+v", b)
269		}
270		// dev-a 仍保留原来的回滚待办（已领取未完成），活动继续执行、结束时间为空。
271		a = dv(d1)
272		if a.Status != DeviceRollingBack || a.RollbackResult || a.RollbackTarget != oldV1 {
273			t.Fatalf("d1 must keep its own rollback pending: %+v", a)
274		}
275		w1, _ := s.GetDeviceWork(d1)
276		if w1.Pending == nil || w1.Pending.Kind != StageRollback || !w1.PendingClaimed ||
277			w1.Pending.ID != rb1.ID || w1.Pending.TargetVersion != oldV1 {
278			t.Fatalf("d1 rollback todo after d2 success: %+v", w1)
279		}
280		if cv = mustGetCampaign(s, cid); cv.Ended || cv.Status != CampaignRunning || !cv.EndedAt.IsZero() {
281			t.Fatalf("campaign still runs while d1 rolls back: %+v", cv)
282		}
283	
284		// dev-a 再提交合规回滚成功，活动这才结束；恢复旧版本不算本次升级成功。
285		rbCfg1 := json.RawMessage(`{"channel":1,"mode":"a","restored":true}`)
286		rb1At := upBase.Add(30 * time.Minute)
287		submit(OperationResult{
288			CampaignID: cid, DeviceID: d1, OperationID: rb1.ID,
289			At: rb1At, Success: true,
290			Seq: 2, Version: oldV1, Config: rbCfg1,
291		})
292		cv = mustGetCampaign(s, cid)
293		if !cv.Ended || cv.Status != CampaignFailed || !cv.EndedAt.Equal(rb1At) {
294			t.Fatalf("campaign ends failed only after both rollbacks: %+v", cv)
295		}
296		a, b = dv(d1), dv(d2)
297		if a.Status != DeviceRollbackSucceeded || b.Status != DeviceRollbackSucceeded {
298			t.Fatalf("both devices rollback_succeeded: %+v %+v", a, b)
299		}
300		if a.Status == DeviceSucceeded || b.Status == DeviceSucceeded {
301			t.Fatal("restoring an old version must not count the upgrade as succeeded")
302		}
303		if !a.RollbackAt.Equal(rb1At) || !b.RollbackAt.Equal(rb2At) ||
304			a.InstallFailReason != "install fail alpha" || b.InstallFailReason != "install fail beta" {
305			t.Fatalf("rollback/install failure records at end: %+v %+v", a, b)
306		}
307	
308		// 两台设备影子：版本回到各自锁定旧版本、上报为各自完整配置；
309		// 期望配置、修订号与审计保持升级前的原有内容。
310		sh1, _ := s.Get(d1)
311		if sh1.Version != oldV1 || !sh1.Online || sh1.LastSeq != 2 || !rawEqual(sh1.Reported, rbCfg1) {
312			t.Fatalf("d1 shadow after rollback: %+v", sh1)
313		}
314		if sh1.Revision != 1 || !rawEqual(sh1.Desired, desired1) {
315			t.Fatalf("d1 desired/revision not preserved: %+v", sh1)
316		}
317		if sh2.Revision != 1 || !rawEqual(sh2.Desired, desired2) {
318			t.Fatalf("d2 desired/revision not preserved: %+v", sh2)
319		}
320		for _, tc := range []struct {
321			id, operator string
322			after        json.RawMessage
323		}{
324			{d1, "ops-a", desired1},
325			{d2, "ops-b", desired2},
326		} {
327			auds, err := s.Audit(tc.id)
328			if err != nil {
329				t.Fatalf("audit %s: %v", tc.id, err)
330			}
331			if len(auds) != 1 || auds[0].Revision != 1 || auds[0].Operator != tc.operator ||
332				string(auds[0].Before) != "{}" || !rawEqual(auds[0].After, tc.after) {
333				t.Fatalf("%s audit must keep original content: %+v", tc.id, auds)
334			}
335		}
336	
337		// 有效结果历史按实际接受顺序保留所属设备、操作标识、阶段、成败与恢复版本；
338		// 每台设备的下载成功、安装失败、回滚成功各留一条，共 6 条。
339		wantHistory := []ResultRecord{
340			{DeviceID: d1, OperationID: dl1.ID, Stage: StageDownload, Success: true, At: upBase.Add(3 * time.Minute)},
341			{DeviceID: d2, OperationID: dl2.ID, Stage: StageDownload, Success: true, At: upBase.Add(6 * time.Minute)},
342			{DeviceID: d1, OperationID: in1.ID, Stage: StageInstall, Success: false, Reason: "install fail alpha", At: fail1At},
343			{DeviceID: d2, OperationID: in2.ID, Stage: StageInstall, Success: false, Reason: "install fail beta", At: fail2At},
344			{DeviceID: d2, OperationID: rb2.ID, Stage: StageRollback, Success: true, Version: oldV2, At: rb2At},
345			{DeviceID: d1, OperationID: rb1.ID, Stage: StageRollback, Success: true, Version: oldV1, At: rb1At},
346		}
347		if len(cv.Results) != len(wantHistory) {
348			t.Fatalf("history len: want %d, got %d: %+v", len(wantHistory), len(cv.Results), cv.Results)
349		}
350		perDevice := map[string]int{}
351		for i, want := range wantHistory {
352			got := cv.Results[i]
353			if got.DeviceID != want.DeviceID || got.OperationID != want.OperationID ||
354				got.Stage != want.Stage || got.Success != want.Success ||
355				got.Reason != want.Reason || got.Version != want.Version || !got.At.Equal(want.At) {
356				t.Fatalf("history[%d]:\n want %+v\n got  %+v", i, want, got)
357			}
358			perDevice[got.DeviceID]++
359		}
360		if perDevice[d1] != 3 || perDevice[d2] != 3 {
361			t.Fatalf("each device must keep exactly 3 records: %+v", perDevice)
362		}
363	}
364

